const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(DEMO_KEY,JSON.stringify({version:1,data:db}))}catch(e){}}
function log(action,detail){db.activity.unshift({at:new Date().toISOString(),action,detail});db.activity=db.activity.slice(0,40);save()}
function fmtDate(d,opts={day:'numeric',month:'short',year:'numeric'}){if(!d)return 'Date inconnue';return new Date(d+'T12:00:00').toLocaleDateString('fr-FR',opts)}
function weekStart(date){let d=new Date(date+'T12:00:00'),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d}
function toISO(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function shiftDate(date,days){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return toISO(d)}
function clientOf(f){return clients.find(c=>c.id===f.clientId)||{name:'Client inconnu'}}
function formOf(s){return formations.find(f=>f.id===s.formationId)}
function sessionById(id){return db.sessions.find(s=>s.id===Number(id))}
function trainerById(id){return trainers.find(t=>t.id===Number(id))}
function activeAssignments(id){return db.assignments.filter(a=>a.sessionId===Number(id)&&['Confirmée','Réalisée'].includes(a.status))}
function openCount(s){return Math.max(0,s.required-activeAssignments(s.id).length)}
function staffingLabel(s){let done=activeAssignments(s.id).length;if(s.status==='Réalisée')return 'Réalisée';if(done>=s.required)return 'Staffing complet';if(done>0)return 'Staffing partiel';if(db.proposals.some(p=>p.sessionId===s.id&&['Prête','Autorisée à l’envoi','Envoyée','Acceptée'].includes(p.status)))return 'Propositions en cours';return 'À staffer'}
function badge(label){let l=String(label??'Inconnu'),cls=/confirm|complet|validé|acceptée|réalisée|disponible|synchronisé/i.test(l)?'green':/attente|staff|prépar|vérification|à fournir|à qualifier|prête|envoyée|partiel|inconnu|non connecté/i.test(l)?'amber':/refus|occupé|expir|retir|erreur|échec|correction|annul|bloqu/i.test(l)?'red':'purple';return `<span class="badge ${cls}">${esc(l)}</span>`}
function intro(title,sub,ey='CERTIF-IA / ESPACE INTERNE'){return `<div class="eyebrow">${esc(ey)}</div><h1 class="headline">${title}</h1><div class="subtitle">${sub}</div>`}
function cardTitle(title,sub=''){return `<div class="card-head"><div><h3 class="section-title">${title}</h3>${sub?`<p class="section-caption">${sub}</p>`:''}</div></div>`}
function metric(name,val,sub,target='',filter='all'){return `<${target?'button':'div'} class="card metric ${target?'metric-action':''}" ${target?`onclick="dashboardGo('${target}','${filter}')" aria-label="Ouvrir ${esc(name)}"`:''}><small>${esc(name)}</small><strong>${esc(val)}</strong><span class="trend">${esc(sub||'Données fictives')}</span>${target?'<span class="metric-arrow">↗</span>':''}</${target?'button':'div'}>`}
function dashboardGo(page,filter){state.filter=filter;state.search='';state.page=page;if(page==='staffing')state.staffTab='todo';if(page==='trainer-missions')state.missionTab=filter==='upcoming'?'upcoming':'proposals';if(page==='trainer-docs')state.trainerDocsFilter='open';navigateHash();render()}
function trainerAvatar(t,size=54){return `<span class="trainer-photo" style="width:${size}px;height:${size}px;background:${t.color};color:${t.accent}">${t.initials}</span>`}
function availabilityBadge(t){return badge(t.available==='yes'?'Disponible déclaré':t.available==='no'?'Occupé déclaré':'Disponibilité inconnue')}
function eventButton(text,action,cls='secondary',attrs=''){return `<button class="${cls}" ${attrs} onclick="${action}">${text}</button>`}
function filtersBar(placeholder,options,fn='onSearch'){return `<div class="toolbar"><div class="filters"><input class="field search" aria-label="Rechercher" placeholder="${esc(placeholder)}" value="${esc(state.search)}" oninput="${fn}(this.value)"><select class="field" aria-label="Filtrer" onchange="onFilter(this.value)">${options.map(([k,v])=>`<option value="${esc(k)}" ${state.filter===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><span class="badge purple">Données fictives</span></div>`}
function onSearch(v){state.search=v;let input=document.activeElement;let pos=input?.selectionStart;render();let out=document.querySelector('.field.search');if(out){out.focus();try{out.setSelectionRange(pos,pos)}catch(e){}}}
function onFilter(v){state.filter=v;render()}
function setRole(value){state.mobileMore=false;if(value.startsWith('trainer-')){state.role='formateur';state.trainerId=Number(value.split('-')[1]);state.page='trainer-home'}else{state.role='amo';state.page='home'}state.menuOpen=false;state.search='';state.filter='all';navigateHash();render()}
function go(page){state.page=page;state.mobileMore=false;state.menuOpen=false;state.modal=null;state.search='';state.filter='all';navigateHash();render();window.scrollTo(0,0)}
function navigateHash(){let hash=(state.role==='formateur'?'formateur':'interne')+'/'+state.page;history.replaceState(null,'','#/'+hash)}
function openFormation(id){state.selectedFormation=id;go('formation-detail')}
function openSession(id){state.selectedSession=Number(id);go('session-detail')}
function openTrainer(id){state.selectedTrainer=Number(id);go('trainer-detail')}
function staffFor(id){state.selectedSession=Number(id);state.staffTab='todo';go('staffing')}
function openModal(kind,id){state.modal={kind,id};render()}
function closeModal(){state.modal=null;render()}
function flash(text){const r=$('toast-root');if(!r)return;r.innerHTML=`<div class="toast" role="status">${esc(text)}</div>`;setTimeout(()=>{if(r)r.innerHTML=''},3500)}
function changeTab(name,value){state[name]=value;render()}
function changeCalendar(direction,person=false){let key=person?'trainerCalendarView':'calendarView',mode=state[key];state.calendarDate=shiftDate(state.calendarDate,direction*(mode==='month'?30:mode==='day'?1:7));render()}
function setCalendar(mode,person=false){state[person?'trainerCalendarView':'calendarView']=mode;render()}
function restoreHash(){let p=location.hash.match(/^#\/(interne|formateur)\/([a-z-]+)$/);if(!p)return;state.role=p[1]==='formateur'?'formateur':'amo';if(validPages(state.role).includes(p[2]))state.page=p[2]}
function validPages(role){return role==='formateur'?['trainer-home','trainer-missions','trainer-calendar','trainer-docs','trainer-profile']:['home','planning','formations','formation-detail','session-detail','trainers','trainer-detail','clients','client-detail','staffing','documents','reporting']}
/* Navigation mobile V1.8 — pure interface, réutilise les écrans métiers V1.7.1. */
const mobileSymbols={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',staff:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 8h5M19.5 5.5v5"/>',docs:'<path d="M3 6a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M7 13h10M7 17h7"/>',more:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',missions:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4.5V3h6v1.5M9 10h6M9 14h6"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',back:'<path d="m14 6-6 6 6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>'};
function mobileIcon(name,size=21){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${mobileSymbols[name]||mobileSymbols.more}</svg>`}
function mobileIsDetail(page){return ['formation-detail','session-detail','trainer-detail','client-detail'].includes(page)}
function mobileBackTarget(page){return ({'formation-detail':'formations','session-detail':'formations','trainer-detail':'trainers','client-detail':'clients'})[page]||'home'}
function mobileTabItems(trainer){return trainer?[['trainer-home','home','Accueil'],['trainer-missions','missions','Missions'],['trainer-calendar','calendar','Agenda'],['trainer-docs','docs','Livrables'],['trainer-profile','profile','Profil']]:[['home','home','Accueil'],['planning','calendar','Agenda'],['staffing','staff','Staffing'],['documents','docs','Livrables'],['more','more','Plus']]}
function mobileIsActive(key,trainer){if(key==='more')return ['formations','formation-detail','session-detail','trainers','trainer-detail','clients','client-detail','reporting'].includes(state.page)||!!state.mobileMore;return state.page===key}
function mobileDock(trainer){return `<nav class="mobile-dock" aria-label="Navigation principale sur téléphone">${mobileTabItems(trainer).map(([key,icon,label])=>`<button type="button" class="mobile-dock-item ${mobileIsActive(key,trainer)?'is-active':''}" ${mobileIsActive(key,trainer)?'aria-current="page"':''} aria-label="${label}" onclick="${key==='more'?'openMobileMore()':`go('${key}')`}"><span class="mobile-dock-icon">${mobileIcon(icon,22)}</span><span class="mobile-dock-label">${label}</span></button>`).join('')}</nav>`}
function mobileHead(trainer,title){const back=mobileIsDetail(state.page);return `<div class="mobile-app-head"><button class="mobile-brand-button" aria-label="${back?'Retour à la liste':'Aller à l’accueil'}" onclick="go('${back?mobileBackTarget(state.page):trainer?'trainer-home':'home'}')">${back?mobileIcon('back',22):'<img src="assets/certifia-icon.png" width="33" height="33" alt=""/>'}</button><div class="mobile-head-center"><span class="mobile-head-eyebrow">${trainer?'PORTAIL FORMATEUR':'CERTIF-IA HUB · AMO'}</span><strong>${esc(title)}</strong></div><button class="mobile-bell" title="Notifications de démonstration" aria-label="Notifications" onclick="flash('Notifications : simulation, aucune connexion réelle')">${mobileIcon('bell',21)}<span class="mobile-bell-dot" aria-hidden="true"></span></button></div>`}
function openMobileMore(){state.mobileMore=true;render()}
function closeMobileMore(){state.mobileMore=false;render()}
function mobileMoreSheet(){if(!state.mobileMore||state.role==='formateur')return '';const choices=[['formations','Formations','Dossiers et sessions'],['trainers','Formateurs','Annuaire & profils'],['clients','Clients','Annuaire & historique'],['reporting','Monthly AMO','Rapport mensuel']];return `<div class="mobile-sheet-overlay" role="presentation" onclick="if(event.target===this)closeMobileMore()"><section class="mobile-more-sheet" role="dialog" aria-modal="true" aria-label="Tous les modules"><div class="mobile-sheet-grip" aria-hidden="true"></div><div class="mobile-sheet-heading"><h2>Explorer le Hub</h2><button type="button" aria-label="Fermer" class="mobile-sheet-close" onclick="closeMobileMore()">${mobileIcon('close',20)}</button></div><div class="mobile-more-list">${choices.map(([page,title,desc])=>`<button type="button" onclick="go('${page}')"><span><strong>${title}</strong><small>${desc}</small></span>${mobileIcon('chevron',19)}</button>`).join('')}</div><div class="mobile-more-settings"><label for="mobile-role-switch">Changer de profil démo</label><select class="field" id="mobile-role-switch" onchange="setRole(this.value)"><option value="amo">AMO / Interne</option>${trainers.map(t=>`<option value="trainer-${t.id}">${esc(t.name)} · Formateur</option>`).join('')}</select><button type="button" onclick="resetDemo()">Réinitialiser les données fictives</button></div></section></div>`}
function decorateMobileTables(){document.querySelectorAll('.tbl').forEach(table=>{const th=[...table.querySelectorAll('thead th')].map(x=>x.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>{[...row.children].forEach((td,i)=>{if(td.tagName==='TD')td.setAttribute('data-mobile-label',th[i]||'Détail')})})})}

function render(){let trainer=state.role==='formateur';if(!validPages(state.role).includes(state.page))state.page=trainer?'trainer-home':'home';let nav=trainer?[
['trainer-home','◫','Mon espace'],['trainer-missions','▦','Mes missions'],['trainer-calendar','▣','Mon agenda'],['trainer-docs','▤','Mes livrables'],['trainer-profile','♧','Mon profil']]:[
['home','◫','Vue d’ensemble'],['planning','▦','Planning global'],['formations','▤','Formations'],['trainers','♧','Formateurs'],['clients','♙','Clients'],['staffing','✧','Staffing assisté'],['documents','▧','Livrables & bilans'],['reporting','◷','Monthly AMO']];
let pageTitle=nav.find(n=>n[0]===state.page)?.[2]||'Détails';let people=trainerById(state.trainerId);document.title='Certif-IA Hub — '+pageTitle;
$('app').innerHTML=`<div class="app"><aside class="sidebar ${state.menuOpen?'open':''}" id="sidebar"><div><img src="assets/certifia-logo.png" class="brand-logo" alt="Certif-IA"><div class="logo-sub">Hub · Espace de démonstration</div></div><div class="nav-label">${trainer?'ESPACE FORMATEUR':'EXPANSION CLIENT'}</div><nav class="nav" aria-label="Navigation principale">${nav.map(([p,ic,label])=>`<button class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''} onclick="go('${p}')"><span class="ic" aria-hidden="true">${ic}</span>${label}</button>`).join('')}</nav><div class="side-bottom"><div class="nav-label">SIMULER UN PROFIL</div><select class="role-select" aria-label="Profil de démonstration" onchange="setRole(this.value)"><option value="amo" ${!trainer?'selected':''}>AMO / Espace interne</option>${trainers.map(t=>`<option value="trainer-${t.id}" ${trainer&&t.id===state.trainerId?'selected':''}>Formateur · ${esc(t.name)}</option>`).join('')}</select><p class="side-note">Démo locale · données et actions fictives<br>Aucune connexion aux outils réels</p><button class="reset-demo" onclick="resetDemo()">↺ Réinitialiser la démo</button><span class="role-badge">● Prototype interactif HTML</span></div></aside>${state.menuOpen?'<button class="sidebar-scrim" aria-label="Fermer le menu" onclick="toggleMenu()"></button>':''}<div class="shell"><header class="topbar">${mobileHead(trainer,pageTitle)}<div class="top-start"><button class="mobile-menu" aria-label="Ouvrir le menu" onclick="toggleMenu()">☰</button><span class="bread">Certif IA &nbsp; / &nbsp; ${trainer?'Formateurs':'Expansion client'} &nbsp; / &nbsp; ${esc(pageTitle)}</span></div><div class="top-right"><span class="pill">✦ Démonstration</span><div class="avatar">${trainer?people.initials:'AM'}</div></div></header><main class="main" id="main-content">${pageContent()}</main></div></div>${mobileDock(trainer)}${mobileMoreSheet()}${state.modal?modalView():''}<div id="toast-root" aria-live="polite"></div>`;
 decorateMobileTables();
}
function toggleMenu(){state.menuOpen=!state.menuOpen;render()}
function resetDemo(){if(!confirm('Réinitialiser toutes les interactions de démonstration ?'))return;db=clone(initialData);save();state.modal=null;state.candidate=null;render();flash('Données de démonstration réinitialisées')}
function pageContent(){return ({home:homePage,planning:planningPage,formations:formationsPage,'formation-detail':formationDetail,'session-detail':sessionDetail,trainers:trainersPage,'trainer-detail':trainerDetail,clients:clientsPage,'client-detail':clientDetail,staffing:staffingPage,documents:documentsPage,reporting:reportingPage,'trainer-home':trainerHome,'trainer-missions':trainerMissions,'trainer-calendar':trainerCalendar,'trainer-docs':trainerDocs,'trainer-profile':trainerProfile})[state.page]?.()||homePage()}
function homePage(){let future=db.sessions.filter(s=>s.status!=='Réalisée');let incomplete=future.filter(s=>openCount(s)>0);let docs=db.deliverables.filter(d=>['À fournir','Correction demandée','En vérification'].includes(d.status));return `${intro('Bonjour <em>à vous.</em>','Une vue claire des formations, des formateurs et des prochaines actions.','CERTIF-IA HUB · DONNÉES FICTIVES')}<div class="cards">${metric('Formations à suivre',formations.length,'Dossiers de formation','formations')}${metric('Staffing à compléter',incomplete.length,'Sessions avec postes ouverts','staffing')}${metric('Formateurs référencés',trainers.length,'Profils fictifs','trainers')}${metric('Livrables à suivre',docs.length,'Documents en cours','documents','open')}</div><div class="two-col"><div class="card">${cardTitle('Prochaines formations','Dossiers et sessions à venir')}${future.sort((a,b)=>a.date.localeCompare(b.date)).slice(0,5).map(s=>`<div class="line-item"><div class="datebox"><strong>${s.date.slice(8)}</strong><small>${fmtDate(s.date,{month:'short'})}</small></div><div class="grow"><div class="item-title">${esc(clientOf(formOf(s)).name)}</div><div class="item-sub">${esc(formOf(s).title)} · ${esc(s.city)} · ${s.start}–${s.end}</div></div>${badge(staffingLabel(s))}<button class="ghost" aria-label="Voir la session" onclick="openSession(${s.id})">↗</button></div>`).join('')}<button class="ghost" style="margin-top:15px" onclick="go('formations')">Voir toutes les formations ↗</button></div><div class="card">${cardTitle('À traiter en priorité','Actions dérivées des scénarios de démo')}<div class="stack">${incomplete.slice(0,3).map(s=>`<div class="task"><span class="bubble">⚡</span><div class="grow"><strong>Staffer ${esc(clientOf(formOf(s)).name)}</strong><p>${openCount(s)} poste(s) à couvrir · ${fmtDate(s.date)}</p></div><button class="ghost" onclick="staffFor(${s.id})">↗</button></div>`).join('')}${docs.slice(0,2).map(d=>`<div class="task"><span class="bubble">📄</span><div class="grow"><strong>${esc(d.title)}</strong><p>${esc(clientOf(formations.find(f=>f.id===d.formationId)).name)} · ${esc(d.status)}</p></div><button class="ghost" onclick="go('documents')">↗</button></div>`).join('')}</div></div></div><div class="banner" style="margin-top:20px"><h2>Une seule interface. Toute la préparation.</h2><p>La même identité graphique que ta maquette d'origine, avec les parcours, statuts et objets métier définis dans Notion.</p><button class="primary" onclick="go('staffing')">Découvrir le staffing assisté →</button></div><p class="footnote">Toutes les entreprises, personnes, dates et opérations sont des exemples fictifs. Les actions ne sont jamais envoyées aux outils réels.</p>`}
function formationsPage(){let rows=formations.filter(f=>{let client=clientOf(f).name,st=db.sessions.filter(s=>s.formationId===f.id);return(client+' '+f.title).toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||(state.filter==='open'&&st.some(s=>openCount(s)>0))||f.status===state.filter)});return `${intro('Les <em>formations.</em>','Une formation regroupe une ou plusieurs sessions, des documents et ses jalons.')}${filtersBar('Client ou formation…',[['all','Tous les dossiers'],['open','Staffing incomplet'],['En préparation','En préparation'],['Planifiée','Planifiée'],['À qualifier','À qualifier']])}<div class="table-wrap"><table class="tbl"><thead><tr><th>Client / Formation</th><th>Sessions</th><th>Dates</th><th>Staffing</th><th>Statut</th><th></th></tr></thead><tbody>${rows.map(f=>{let ss=db.sessions.filter(s=>s.formationId===f.id);return `<tr><td><strong>${esc(clientOf(f).name)}</strong><div class="item-sub">${esc(f.title)}</div></td><td>${ss.length} session(s)</td><td>${ss.map(s=>fmtDate(s.date,{day:'numeric',month:'short'})).join(' · ')}</td><td>${ss.filter(s=>openCount(s)===0).length}/${ss.length} session(s) staffées</td><td>${badge(f.status)}</td><td><button class="ghost" onclick="openFormation('${f.id}')">Voir ↗</button></td></tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty">Aucune formation trouvée.</div>'}</div><p class="footnote">Une formation n’est pas dupliquée par ses sessions. Les statuts de staffing sont calculés à partir des affectations confirmées.</p>`}
const milestones=[['J-28','Audit'],['J-14','Cadrage'],['J-7','Programme PDF'],['J-3','Feu vert'],['J-1','Vérifications'],['Jour J','Questionnaire'],['J+1','Débrief'],['J+7','Bilan / passation']];
function formationDetail(){let f=formations.find(x=>x.id===state.selectedFormation)||formations[0],ss=db.sessions.filter(s=>s.formationId===f.id),docs=db.deliverables.filter(d=>d.formationId===f.id);return `<button class="ghost" onclick="go('formations')">← Retour aux formations</button>${intro(esc(clientOf(f).name),esc(f.title),'FICHE FORMATION · DONNÉES FICTIVES')}<div class="toolbar">${badge(f.status)}<div class="group">${badge(ss.length+' session(s)')}<span class="badge blue">Données HubSpot simulées</span></div></div><div class="detail-grid"><div><div class="card">${cardTitle('Sessions de formation','Chaque session conserve son propre staffing et ses horaires')}${ss.map(s=>`<div class="line-item"><div class="datebox"><strong>${s.date.slice(8)}</strong><small>${fmtDate(s.date,{month:'short'})}</small></div><div class="grow"><div class="item-title">${esc(s.topic)} · ${esc(s.city)}</div><div class="item-sub">${s.start}–${s.end} · ${s.required} formateur(s) requis</div></div>${badge(staffingLabel(s))}<button class="ghost" onclick="openSession(${s.id})">Détail ↗</button></div>`).join('')}</div><div class="card" style="margin-top:18px">${cardTitle('Cycle de préparation','Jalons AMO de J-28 à J+7')}<div class="milestone-grid">${milestones.map(([date,name],i)=>`<div class="milestone"><span class="milestone-date">${date}</span><strong>${name}</strong><small>${i<2?'Étape indicative':'À contrôler selon le dossier'}</small></div>`).join('')}</div></div></div><div><div class="card">${cardTitle('Livrables associés')}${docs.length?docs.map(d=>docLine(d)).join(''):'<div class="empty">Aucun document recensé.</div>'}<button class="secondary" style="margin-top:14px" onclick="go('documents')">Tous les livrables ↗</button></div><div class="card" style="margin-top:18px">${cardTitle('Sources prévues')}${db.sync.map(c=>`<div class="line-item"><div class="grow"><strong>${esc(c.name)}</strong><div class="item-sub">Intégration à venir</div></div>${badge(c.status)}</div>`).join('')}</div></div></div>`}
function sessionDetail(){let s=sessionById(state.selectedSession)||db.sessions[0],f=formOf(s),aa=activeAssignments(s.id),p=db.proposals.filter(p=>p.sessionId===s.id),docs=db.deliverables.filter(d=>d.sessionId===s.id);return `<button class="ghost" onclick="openFormation('${f.id}')">← Retour à la formation</button>${intro(esc(clientOf(f).name),esc(f.title),'FICHE SESSION · EXEMPLE FICTIF')}<div class="toolbar"><div class="group">${badge(s.status)}${badge(staffingLabel(s))}</div><button class="primary" onclick="staffFor(${s.id})">Gérer le staffing →</button></div><div class="detail-grid"><div><div class="card">${cardTitle('Informations de la session')}<div class="info-grid">${[['Date',fmtDate(s.date)],['Horaires',s.start+'–'+s.end],['Lieu',s.city],['Participants',s.people+' personnes'],['Modalité',s.modality],['Formateurs nécessaires',s.required],['Statut session',s.status],['Affectations confirmées',aa.length]].map(([k,v])=>`<div class="info"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div></div><div class="card" style="margin-top:18px">${cardTitle('Affectations et propositions')}${aa.map(a=>`<div class="line-item"><div class="grow"><strong>${esc(trainerById(a.trainerId)?.name)}</strong><div class="item-sub">Affectation ${esc(a.id)}</div></div>${badge(a.status)}</div>`).join('')}${p.map(x=>`<div class="line-item"><div class="grow"><strong>${esc(trainerById(x.trainerId)?.name)}</strong><div class="item-sub">Proposition ${esc(x.id)}</div></div>${badge(x.status)}</div>`).join('')}${!aa.length&&!p.length?'<div class="empty">Aucune affectation ni proposition.</div>':''}</div><div class="card" style="margin-top:18px">${cardTitle('Documents et livrables')}${docs.map(d=>docLine(d)).join('')||'<div class="empty">Aucun livrable pour cette session.</div>'}</div></div><div><div class="card">${cardTitle('Modifier la session','L’impact sur les affectations sera signalé')}<button class="secondary" onclick="openModal('reschedule',${s.id})">🗓 Reporter la session</button><button class="secondary" style="margin-top:9px" onclick="go('planning')">Voir dans le planning</button></div><div class="card" style="margin-top:18px">${cardTitle('Traçabilité','État de démo')}${db.activity.filter(a=>a.detail.includes(String(s.id))).slice(0,5).map(a=>`<div class="line-item"><div class="grow"><strong>${esc(a.action)}</strong><div class="item-sub">${esc(a.detail)}</div></div></div>`).join('')||'<div class="empty">Aucune action enregistrée.</div>'}</div></div></div>`}
function trainersPage(){let rows=trainers.filter(t=>(state.filter==='all'||(state.filter==='unknown'&&t.available==='unknown')||(state.filter==='available'&&t.available==='yes')||t.city===state.filter)&&(t.name+' '+t.skills.join(' ')+' '+t.city).toLowerCase().includes(state.search.toLowerCase()));return `${intro('Les <em>formateurs.</em>','Annuaire enrichi — LinkedIn, expertises, expérience et performances, visibles uniquement selon les droits internes.')}${filtersBar('Nom, compétence, ville…',[['all','Tous les profils'],['available','Disponibles déclarés'],['unknown','Disponibilité inconnue'],['Paris','Paris'],['Lyon','Lyon'],['Bordeaux','Bordeaux'],['Marseille','Marseille']])}<div class="toolbar"><div class="group"><button class="${state.trainerView==='cards'?'primary':'secondary'} tiny" onclick="changeTab('trainerView','cards')">▦ Cards</button><button class="${state.trainerView==='table'?'primary':'secondary'} tiny" onclick="changeTab('trainerView','table')">☷ Tableau</button></div><span class="badge purple">Référentiel Notion à connecter · données fictives</span></div>${state.trainerView==='cards'?`<div class="trainer-grid">${rows.map(t=>{let x=trainerProfileField(t.id);return `<div class="trainer-card"><div class="trainer-top">${trainerAvatar(t)}<div><div class="trainer-name">${esc(t.name)}</div><div class="trainer-meta">⌖ ${esc(t.city)} · ${esc(t.rating)}</div></div></div><div class="tags">${t.skills.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div>${availabilityBadge(t)}<div style="margin:9px 0">${reliabilityBadge(t)}</div><div class="trainer-stats v19-three"><div><small>Missions (démo)</small><strong>${t.missions}</strong></div><div><small>TJM TTC</small><strong>${money(t.rate)}</strong></div><div><small>Gains estimés*</small><strong>${money(gainsEstimate(t))}</strong></div></div><div class="item-sub">${esc(x.domain)} · ${x.nps==null?'NPS inconnu':'Satisfaction '+x.nps+'/10'}</div><div class="split-btns" style="margin-top:14px"><button class="secondary tiny" onclick="openTrainer(${t.id})">Voir la fiche</button><button class="primary tiny" onclick="selectTrainerForStaff(${t.id})">Staffer</button></div></div>`}).join('')}</div>`:`<div class="table-wrap"><table class="tbl"><thead><tr><th>Formateur</th><th>Classement</th><th>Spécialité</th><th>TJM TTC</th><th>NPS (démo)</th><th>Fiabilité</th><th>Gains estimés</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.name)}</strong><div class="item-sub">${esc(t.city)}</div></td><td>${esc(t.rating)}</td><td>${esc(trainerProfileField(t.id).domain)}</td><td>${t.rate} €</td><td>${trainerProfileField(t.id).nps??'Inconnu'}</td><td>${reliabilityBadge(t)}</td><td>${money(gainsEstimate(t))}</td><td><button class="ghost" onclick="openTrainer(${t.id})">Voir ↗</button></td></tr>`).join('')}</tbody></table></div>`}<p class="footnote">Schéma cible de <a class="text-link" href="https://app.notion.com/p/3e5c6d0eb96e809ab965c7f66813ffd8" target="_blank" rel="noopener noreferrer">Formateurs à staffer Q4 26 ↗</a> : Activité, Classement, LinkedIn, LLM, spécialités, localisation, TJM (TTC), NPS moyen, nombre de missions et cartons. Aucun profil réel n'a été importé ici.</p>`}
function selectTrainerForStaff(id){state.candidate=id;go('staffing')}
function trainerDetail(){
 if(state.role==='formateur')return '<div class="empty">Accès réservé à l’équipe interne.</div>';
 const t=trainerById(state.selectedTrainer)||trainers[0],x=trainerProfileField(t.id),aa=db.assignments.filter(a=>a.trainerId===t.id),tab=state.trainerDetailTab||'overview';
 const tabs=[['overview','Présentation'],['career','Profil professionnel'],['missions','Missions & scores'],['performance','Performances'],['internal','Gestion interne'],['agenda','Planning & staffing']];
 let content='';
 if(tab==='overview')content=`<div class="info-grid">${[['Activité',x.activity],['Classement',t.rating],['Spécialité',x.domain],['LLM',x.llm.join(', ')||'Inconnu'],['Localisation',t.city],['TJM TTC',money(t.rate)],['Missions fictives',t.missions],['NPS démo',x.nps==null?'Non renseigné':x.nps+'/10']].map(([k,v])=>`<div class="info"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}<div class="info"><small>E-mail</small>${safeContact(t.email,'email')}</div><div class="info"><small>Téléphone</small>${safeContact(x.phone,'phone')}</div><div class="info"><small>LinkedIn</small>${linkSafe(x.linkedin,'Ouvrir le profil')}</div></div><p class="footnote">Contacts fictifs ou absents : à synchroniser avec la base Notion autorisée, sans inventer de numéro ni de profil LinkedIn.</p>`;
 else if(tab==='career')content=`<div class="profile-columns">${[['Expériences',x.experience],['Domaine et connaissances',[x.domain,...x.knowledge]],['Forces',x.strengths],['Axes d’amélioration (interne)',x.improvements]].map(([name,list])=>`<div class="info"><small>${esc(name)}</small>${list.map(v=>`<p>• ${esc(v)}</p>`).join('')||'<p>Non renseigné</p>'}</div>`).join('')}</div>`;
 else if(tab==='missions')content=`<h3 class="section-title">Historique des missions</h3>${aa.map(a=>{let s=sessionById(a.sessionId),r=missionRatings[a.id];return `<div class="line-item"><div class="grow"><strong>${esc(clientOf(formOf(s)).name)} · ${esc(formOf(s).title)}</strong><div class="item-sub">${fmtDate(s.date)} · ${esc(s.city)}</div></div>${badge(r?.score!=null?r.score+'/10 · démo':'Non évaluée')}<button class="ghost" onclick="openSession(${s.id})">Détail ↗</button></div>`}).join('')||'<div class="empty">Aucune mission.</div>'}`;
 else if(tab==='performance')content=`<div class="cards">${metric('NPS moyen',x.nps==null?'Inconnu':x.nps+'/10','Donnée fictive')}${metric('Missions recensées',aa.length,'Dans la démo')}</div>${reliabilityCard(t)}`;
 else if(tab==='internal')content=internalReviewsCard(t);
 else content=`${availabilityBadge(t)}<div class="info" style="margin:16px 0"><small>Calendrier</small><strong>${esc(t.city)} · ${esc(x.domain)}</strong><p>Google Agenda non connecté.</p></div>${db.availability.filter(a=>a.trainerId===t.id).map(a=>`<div class="line-item">${fmtDate(a.date)} · ${esc(a.start||'Journée')} ${badge(a.status)}</div>`).join('')||'<div class="empty">Aucun créneau déclaré.</div>'}<button class="primary" onclick="selectTrainerForStaff(${t.id})">Préparer un staffing →</button>`;
 return `<button class="ghost" onclick="go('trainers')">← Retour à l’annuaire</button><div class="card" style="margin-top:15px"><div class="trainer-top">${trainerAvatar(t,70)}<div><h1 class="headline" style="font-size:28px;margin:0">${esc(t.name)}</h1><div class="trainer-meta">${esc(t.city)} · ${esc(t.rating)}</div>${reliabilityBadge(t)}</div><div class="grow"></div>${availabilityBadge(t)}</div><div class="tabs tabs-scroll">${tabs.map(([key,label])=>`<button class="${key===tab?'selected':''}" onclick="changeTab('trainerDetailTab','${key}')">${label}</button>`).join('')}</div>${content}</div>`;
}
function reliabilityCard(t){let score=reliabilityScore(t);return `<div class="card" style="margin-top:16px"><div class="card-head"><div><h3 class="section-title">Fiabilité · grille proposée V1.9</h3><p class="section-caption">Satisfaction 40 %, ponctualité 30 %, incidents vérifiés 20 %, retours de missions 10 %</p></div>${badge('À valider métier')}</div>${score.parts.map(([label,value,weight])=>`<div class="line-item"><div class="grow"><strong>${esc(label)}</strong> <small>(${weight} %)</small></div><strong>${value==null?'Données insuffisantes':value+'/100'}</strong></div>`).join('')}<p class="footnote">${score.total===null?'Fiabilité non évaluée : des critères ne sont pas renseignés.':'Indice de démonstration : '+score.total+'/100.'} Pas de bonus/malus appliqué à une personne réelle. Les données manquantes ne sont jamais considérées comme zéro.</p></div>`;}
function openClient(id){state.selectedClient=id;go('client-detail')}
function clientsPage(){let rows=clients.filter(c=>(state.filter==='all'||clientDetails[c.id]?.city===state.filter)&&(c.name+' '+(clientDetails[c.id]?.industry||'')).toLowerCase().includes(state.search.toLowerCase()));return `${intro('Annuaire <em>clients.</em>','Un espace pour relier les dossiers HubSpot, les formations et les formateurs déjà mobilisés.')}${filtersBar('Client, secteur…',[['all','Tous les clients'],['Paris','Paris'],['Lyon','Lyon'],['Bordeaux','Bordeaux']])}<div class="toolbar"><div class="group"><button class="${state.clientView==='cards'?'primary':'secondary'} tiny" onclick="changeTab('clientView','cards')">▦ Cards</button><button class="${state.clientView==='table'?'primary':'secondary'} tiny" onclick="changeTab('clientView','table')">☷ Tableau</button></div><span class="badge purple">HubSpot non connecté · clients fictifs</span></div>${state.clientView==='cards'?`<div class="trainer-grid">${rows.map(c=>{let d=clientDetails[c.id],fs=formations.filter(f=>f.clientId===c.id),ts=assignedTrainersOfClient(c.id);return `<div class="trainer-card"><div class="trainer-top"><span class="client-avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><div><div class="trainer-name">${esc(c.name)}</div><div class="trainer-meta">${esc(d.city)} · ${esc(d.industry)}</div></div></div><div class="tags">${ts.map(t=>`<span class="tag">${esc(t.name)}</span>`).join('')||'<span class="tag">Aucun formateur confirmé</span>'}</div><div class="trainer-stats"><div><small>Formations</small><strong>${fs.length}</strong></div><div><small>Formateurs intervenus</small><strong>${ts.length}</strong></div></div><button class="primary" onclick="openClient('${c.id}')">Voir la fiche client →</button></div>`}).join('')}</div>`:`<div class="table-wrap"><table class="tbl"><thead><tr><th>Client</th><th>Secteur</th><th>Ville</th><th>Formations</th><th>Formateurs associés</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(clientDetails[c.id].industry)}</td><td>${esc(clientDetails[c.id].city)}</td><td>${formations.filter(f=>f.clientId===c.id).length}</td><td>${assignedTrainersOfClient(c.id).length}</td><td><button class="ghost" onclick="openClient('${c.id}')">Voir ↗</button></td></tr>`).join('')}</tbody></table></div>`}<p class="footnote">Données fictives : les informations HubSpot, interlocuteurs et contacts réels ne sont pas intégrés à cette démo.</p>`}
function clientDetail(){let c=clientById(state.selectedClient)||clients[0],d=clientDetails[c.id],fs=formations.filter(f=>f.clientId===c.id),ts=assignedTrainersOfClient(c.id);return `<button class="ghost" onclick="go('clients')">← Annuaire clients</button><div class="card" style="margin-top:15px"><h1 class="headline">${esc(c.name)}</h1><div class="info-grid">${[['Secteur',d.industry],['Ville',d.city],['Collaborateurs (exemple)',d.employees],['Contact',d.contact],['Référence CRM',d.hubspot],['Adresse',d.address||'À renseigner depuis le CRM']].map(([k,v])=>`<div class="info"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3 class="section-title" style="margin:25px 0 8px">Formateurs ayant travaillé pour ce client</h3>${ts.length?ts.map(t=>`<div class="line-item">${trainerAvatar(t,40)}<div class="grow"><strong>${esc(t.name)}</strong><div class="item-sub">${esc(t.rating)}</div></div><button class="ghost" onclick="openTrainer(${t.id})">Profil ↗</button></div>`).join(''):'<div class="empty">Aucune affectation confirmée dans la démo</div>'}<h3 class="section-title" style="margin:25px 0 8px">Historique des formations</h3>${fs.flatMap(f=>f.sessionIds.map(id=>{let s=sessionById(id);return `<div class="line-item"><div class="grow"><strong>${esc(f.title)}</strong><div class="item-sub">${fmtDate(s.date)} · ${esc(s.city)} · ${esc(staffingLabel(s))}</div></div><button class="ghost" onclick="openSession(${s.id})">Session ↗</button></div>`})).join('')}</div><p class="footnote">Fiche client interne : à connecter à HubSpot avant affichage de contacts, notes et informations réelles.</p>`}
function criteria(t,s){let exact=t.skills.some(k=>k.toLowerCase()===s.topic.toLowerCase()),related=t.skills.some(k=>k.toLowerCase().includes(s.topic.toLowerCase())||s.topic.toLowerCase().includes(k.toLowerCase()));return [exact?'Expertise exacte':related?'Expertise proche':'Expertise à vérifier',t.city===s.city?'Même ville':'Déplacement à confirmer',t.available==='yes'?'Disponibilité déclarée':t.available==='no'?'Occupé déclaré':'Disponibilité inconnue']}
function staffingPage(){let s=sessionById(state.selectedSession)||db.sessions[0],open=db.sessions.filter(x=>x.status!=='Réalisée'&&openCount(x)>0),confirmed=db.assignments.filter(x=>x.status==='Confirmée'),pending=db.proposals.filter(p=>!['Refusée','Expirée','Retirée'].includes(p.status));return `${intro('Staffing <em>assisté.</em>','Propositions et affectations séparées · matching explicable et validation humaine.') }<div class="tabs">${[['todo','À staffer'],['proposals','Propositions en cours'],['confirmed','Confirmées']].map(([key,label])=>`<button class="${state.staffTab===key?'selected':''}" onclick="changeTab('staffTab','${key}')">${label}</button>`).join('')}</div>${state.staffTab==='todo'?`<div class="toolbar"><div class="group"><label for="staff-session"><strong>Session à staffer</strong></label><select id="staff-session" class="field" onchange="state.selectedSession=Number(this.value);state.candidate=null;render()">${db.sessions.filter(x=>x.status!=='Réalisée').map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(clientOf(formOf(x)).name)} · ${fmtDate(x.date,{day:'numeric',month:'short'})}</option>`).join('')}</select></div>${badge(staffingLabel(s))}</div><div class="detail-grid"><div class="card">${cardTitle('Formateurs suggérés','Matching fictif : pondération 40 / 30 / 20 / 10, explication accessible au clic')}${trainers.map(t=>`<div class="candidate ${state.candidate===t.id?'selected':''}">${trainerAvatar(t,44)}<div class="grow"><div class="item-title">${esc(t.name)}</div><div class="item-sub">${esc(t.city)} · ${t.rate} €/jour</div><div class="tags" style="margin:7px 0">${criteria(t,s).map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div></div><button class="score-pill" onclick="openModal('matching',${t.id})" title="Voir le détail du score">${compatDetails(t,s).total}% ⓘ</button><button class="${state.candidate===t.id?'primary':'secondary'} tiny" onclick="state.candidate=${t.id};render()">${state.candidate===t.id?'Sélectionné':'Choisir'}</button></div>`).join('')}<p class="footnote">Pour confirmer, vérifiez les disponibilités, les conditions et les capacités. Un calendrier vide n’est pas une preuve de disponibilité.</p></div><div class="card">${cardTitle('Mission sélectionnée')}<div class="mini-heading">Client</div><strong>${esc(clientOf(formOf(s)).name)}</strong><div class="mini-heading">Formation</div><strong>${esc(formOf(s).title)}</strong><div class="mini-heading">Session</div><div class="item-sub">📍 ${esc(s.city)}<br>🗓 ${fmtDate(s.date)} · ${s.start}–${s.end}<br>♧ ${s.people} participants</div><div class="mini-heading">Places à pourvoir</div>${badge(openCount(s)+' / '+s.required)}<div class="mini-heading">Formateur sélectionné</div><strong>${state.candidate?esc(trainerById(state.candidate).name):'Aucun pour le moment'}</strong><button class="primary" style="width:100%;margin-top:18px" ${!state.candidate||openCount(s)===0?'disabled':''} onclick="createProposal()">Préparer une proposition →</button><button class="secondary" style="width:100%;margin-top:9px" onclick="openSession(${s.id})">Voir la fiche session</button></div></div>`:state.staffTab==='proposals'?`<div class="card">${cardTitle('Cycle des propositions','Brouillon → autorisation humaine → envoi simulé → réponse → affectation à confirmer')}${pending.length?pending.map(p=>{let t=trainerById(p.trainerId),s=sessionById(p.sessionId);return `<div class="line-item"><div class="grow"><strong>${esc(t?.name)} · ${esc(clientOf(formOf(s)).name)}</strong><div class="item-sub">${fmtDate(s.date)} · ${esc(p.conditions)} · ${esc(p.id)}</div></div>${badge(p.status)}<div class="action-wrap">${p.status==='Brouillon'?eventButton('Autoriser','approveProposal(\''+p.id+'\')','secondary tiny'):''}${p.status==='Autorisée à l’envoi'?eventButton('Marquer envoyé (démo)','sendProposal(\''+p.id+'\')','primary tiny'):''}${p.status==='Acceptée'?eventButton('Confirmer affectation','confirmAssignment(\''+p.id+'\')','primary tiny'):''}${p.status==='Envoyée'?eventButton('Voir le portail','setRole(\'trainer-'+p.trainerId+'\')','secondary tiny'):''}</div></div>`}).join(''):'<div class="empty">Aucune proposition en cours.</div>'}</div>`:`<div class="card">${cardTitle('Affectations confirmées')}${confirmed.map(a=>{let s=sessionById(a.sessionId);return `<div class="line-item"><div class="grow"><strong>${esc(trainerById(a.trainerId)?.name)}</strong><div class="item-sub">${esc(clientOf(formOf(s)).name)} · ${fmtDate(s.date)} · ${esc(a.id)}</div></div>${badge(a.status)}<button class="ghost" onclick="openSession(${s.id})">Détail ↗</button></div>`}).join('')||'<div class="empty">Aucune affectation confirmée.</div>'}</div>`}<p class="footnote">État local de démonstration persistant dans ce navigateur. Aucun WhatsApp, e-mail, Slack ou HubSpot n'est appelé.</p>`}
function createProposal(){let s=sessionById(state.selectedSession),t=trainerById(state.candidate);if(!s||!t||openCount(s)===0)return flash('Aucune place disponible');let existing=db.proposals.find(p=>p.sessionId===s.id&&p.trainerId===t.id&&!['Refusée','Expirée','Retirée'].includes(p.status));if(existing)return flash('Une proposition active existe déjà pour ce formateur');let id='P'+(Math.max(1,...db.proposals.map(p=>Number(p.id.slice(1))))+1);db.proposals.push({id,sessionId:s.id,trainerId:t.id,status:'Brouillon',approved:false,sent:false,conditions:`${t.rate} € / jour · ${s.modality}`,created:'2026-11-10',expires:null});log('Proposition préparée',`${id} · session ${s.id}`);state.staffTab='proposals';render();flash('Brouillon créé (simulation)')}
function approveProposal(id){let p=db.proposals.find(x=>x.id===id);if(!p||p.status!=='Brouillon')return flash('Proposition non autorisable');p.approved=true;p.status='Autorisée à l’envoi';log('Autorisation humaine simulée',id);render();flash('Envoi autorisé (simulation)')}
function sendProposal(id){let p=db.proposals.find(x=>x.id===id);if(!p||!p.approved||p.status!=='Autorisée à l’envoi')return flash('Validation humaine requise');p.status='Envoyée';p.sent=true;log('Envoi simulé — aucun message réel',id);render();flash('Statut Envoyée — simulation uniquement')}
function respondProposal(id,status){let p=db.proposals.find(x=>x.id===id);if(!p||p.trainerId!==state.trainerId||p.status!=='Envoyée')return flash('Cette proposition ne peut plus recevoir de réponse');p.status=status;log('Réponse formateur : '+status,id);render();flash('Réponse '+status.toLowerCase()+' enregistrée dans la démo')}
function confirmAssignment(id){let p=db.proposals.find(x=>x.id===id);if(!p||p.status!=='Acceptée')return flash('Une acceptation active est requise');let s=sessionById(p.sessionId);if(openCount(s)===0)return flash('Session déjà entièrement staffée : arbitrage nécessaire');if(trainerById(p.trainerId)?.available==='no')return flash('Formateur occupé : vérifiez le conflit avant confirmation');let existing=db.assignments.some(a=>a.sessionId===s.id&&a.trainerId===p.trainerId&&a.status==='Confirmée');if(existing)return flash('Affectation déjà confirmée');let next='A'+(Math.max(0,...db.assignments.map(a=>Number(a.id.slice(1))))+1);db.assignments.push({id:next,sessionId:s.id,trainerId:p.trainerId,status:'Confirmée',proposalId:id});log('Affectation confirmée (démo)',`${next} · session ${s.id}`);render();flash('Affectation confirmée en démo · synchronisation externe absente')}
function planningPage(){return `${intro('Planning <em>global.</em>','Vue synchronisée de démonstration : superposez plusieurs agendas et modifiez les sessions sous contrôle.') }<div class="card" style="margin-bottom:18px">${cardTitle('Agendas des formateurs','Sélectionnez un ou plusieurs formateurs pour visualiser leurs créneaux en parallèle')}<div class="agenda-pickers"><button class="secondary tiny" onclick="selectAllAgendas(true)">Tout sélectionner</button><button class="secondary tiny" onclick="selectAllAgendas(false)">Tout masquer</button>${trainers.map(t=>`<label class="agenda-option"><input type="checkbox" ${state.selectedAgendaIds.includes(t.id)?'checked':''} onchange="toggleAgenda(${t.id},this.checked)"><span class="agenda-color" style="background:${t.accent}"></span><span>${esc(t.name)}</span></label>`).join('')}</div><div class="toolbar"><div class="group"><label><input type="checkbox" ${state.agendaShow==='both'||state.agendaShow==='availability'?'checked':''} onchange="state.agendaShow=this.checked?'both':'missions';render()"> Afficher les disponibilités / indisponibilités</label></div><span class="badge purple">Événements privés masqués · disponibilité inconnue ≠ libre</span></div></div>${calendarUI(false)}<div class="card" style="margin-top:18px">${cardTitle('Sessions et modifications','Modifier date, horaires, lieu, modalité et formateur ; revalidation des affectations')} ${db.sessions.filter(s=>s.status!=='Réalisée').sort((a,b)=>a.date.localeCompare(b.date)).map(s=>`<div class="line-item"><div class="datebox"><strong>${s.date.slice(8)}</strong><small>${fmtDate(s.date,{month:'short'})}</small></div><div class="grow"><strong>${esc(clientOf(formOf(s)).name)}</strong><div class="item-sub">${s.start}–${s.end} · ${esc(s.city)} · ${esc(activeAssignments(s.id).map(a=>trainerById(a.trainerId)?.name).join(', ')||'À staffer')}</div></div><button class="secondary tiny" onclick="openModal('edit-session',${s.id})">Modifier</button></div>`).join('')}</div>`}
function selectAllAgendas(yes){state.selectedAgendaIds=yes?trainers.map(t=>t.id):[];render()}
function toggleAgenda(id,checked){state.selectedAgendaIds=checked?[...state.selectedAgendaIds,id]:state.selectedAgendaIds.filter(t=>t!==id);render()}
function calendarUI(person){let view=state[person?'trainerCalendarView':'calendarView'],date=state.calendarDate,d=new Date(date+'T12:00:00'),from=view==='month'?new Date(d.getFullYear(),d.getMonth(),1,12):view==='week'?weekStart(date):d;let days=view==='month'?Array.from({length:new Date(d.getFullYear(),d.getMonth()+1,0).getDate()},(_,i)=>toISO(new Date(d.getFullYear(),d.getMonth(),i+1,12))):Array.from({length:view==='day'?1:7},(_,i)=>toISO(new Date(from.getFullYear(),from.getMonth(),from.getDate()+i,12)));
let sessions=person?db.sessions.filter(s=>activeAssignments(s.id).some(a=>a.trainerId===state.trainerId)):db.sessions.filter(s=>activeAssignments(s.id).some(a=>state.selectedAgendaIds.includes(a.trainerId))||openCount(s)>0);
let av=person?db.availability.filter(a=>a.trainerId===state.trainerId):db.availability.filter(a=>state.selectedAgendaIds.includes(a.trainerId)&&(state.agendaShow==='both'||state.agendaShow==='availability'));
let box=day=>`<div class="cal-day ${day===date?'current-day':''}"><div class="cal-day-label">${fmtDate(day,{weekday:'short',day:'numeric',month:'short'})}</div>${sessions.filter(s=>s.date===day).map(s=>{let names=activeAssignments(s.id).filter(a=>person||state.selectedAgendaIds.includes(a.trainerId)).map(a=>trainerById(a.trainerId)?.name).filter(Boolean);return `<button class="event mini-event ${openCount(s)===0?'green':'amber'}" onclick="openSessionFromCalendar(${s.id},${person})">${esc(clientOf(formOf(s)).name)}<small>${s.start}–${s.end} · ${esc(names.join(', ')||'À staffer')}</small></button>`}).join('')}${av.filter(a=>a.date===day).map(a=>`<div class="event mini-event ${a.status==='Occupé'?'red':'green'}" title="Détails personnels masqués">${person?'Moi':esc(trainerById(a.trainerId)?.name||'Formateur')} — ${esc(a.status)}<small>${esc(a.start||'Journée')} ${a.end?'– '+esc(a.end):''}${a.zone?' · '+esc(a.zone):''} · déclaratif</small></div>`).join('')}${!sessions.some(s=>s.date===day)&&!av.some(a=>a.date===day)?'<span class="cal-no-event">Aucune information : disponibilité inconnue</span>':''}</div>`;
return `<div class="toolbar"><div class="group"><button class="secondary tiny" onclick="changeCalendar(-1,${person})">‹</button><strong>${fmtDate(date,{month:'long',year:'numeric'})}</strong><button class="secondary tiny" onclick="changeCalendar(1,${person})">›</button><button class="secondary tiny" onclick="state.calendarDate='2026-11-12';render()">Date démo</button></div><div class="group">${[['month','Mois'],['week','Semaine'],['day','Jour']].map(([key,label])=>`<button class="${key===view?'primary':'secondary'} tiny" onclick="setCalendar('${key}',${person})">${label}</button>`).join('')}</div></div><div class="calendar"><div class="cal-adaptive ${view==='month'?'month-view':view==='day'?'day-view':'week-view'}">${days.map(box).join('')}</div></div><div class="legend" style="margin:15px 0"><span><i class="dot green"></i>Mission confirmée ou libre déclaré</span><span><i class="dot amber"></i>À staffer</span><span><i class="dot red"></i>Occupé déclaré</span></div><p class="footnote">Aucun titre, motif ou participant d'agenda privé n'apparaît côté AMO. Google Agenda n'est pas connecté dans cette démo.</p>`}
function openSessionFromCalendar(id,person){if(person){state.selectedSession=id;go('trainer-missions')}else openSession(id)}

const documentColumns=[['AUDIT','Audit'],['CADRAGE','Cadrage (Audit)'],['PROGRAMME','Programme PDF'],['SUPPORT','Support'],['BILANS','Bilan']];
function docCategory(d){const type=(d.type||'').toUpperCase(),title=(d.title||'').toLowerCase();if(type==='CADRAGE'||title.includes('cadrage'))return 'CADRAGE';if(type==='AUDIT')return 'AUDIT';if(type==='PROGRAMME')return 'PROGRAMME';if(type==='SUPPORT')return 'SUPPORT';if(type==='BILANS'||type==='BILAN')return 'BILANS';return type;}
function docConformity(d){if(!d||!d.versions?.length||d.status==='À fournir'||d.status==='Correction demandée')return 'miss';const file=d.versions.at(-1).filename||'';if(docCategory(d)==='PROGRAMME'&&!/\.pdf$/i.test(file))return 'part';return 'ok';}
function documentMatrix(f,person=false){let ds=db.deliverables.filter(d=>d.formationId===f.id&&(!person||(d.owner==='formateur'&&d.trainerId===state.trainerId)));let cols=(person?[...new Set(ds.map(docCategory))].map(key=>documentColumns.find(c=>c[0]===key)||[key,key]):documentColumns);return cols.map(([key,label])=>{let d=ds.find(d=>docCategory(d)===key);return {key,label,d,status:docConformity(d)};});}
function docStatsFor(f,person=false){let matrix=documentMatrix(f,person);let conform=matrix.filter(x=>x.status==='ok').length;let toCheck=matrix.filter(x=>x.d?.versions?.length&&x.d.status!=='Validé').length;let verified=matrix.filter(x=>x.d?.status==='Validé').length;return {matrix,conform,toCheck,verified,missing:matrix.filter(x=>x.status==='miss').length,percentage:matrix.length?Math.round(100*conform/matrix.length):0};}
function matrixStatus(x){let icon=x.status==='ok'?'✓':x.status==='part'?'~':'✕',word=x.status==='ok'?'Présent et conforme':x.status==='part'?'Présent, format non conforme':'Manquant';return `<span class="v19-marker ${x.status}" title="${esc(x.label+': '+word)}" aria-label="${esc(x.label+': '+word)}">${icon}</span>`;}
function docGridRow(f){let stats=docStatsFor(f);const next=db.sessions.filter(s=>s.formationId===f.id&&s.status!=='Réalisée').sort((a,b)=>a.date.localeCompare(b.date))[0];return `<tr><td><strong>${esc(clientOf(f).name)}</strong><div class="item-sub">${esc(f.title)} · ${next?'À venir '+fmtDate(next.date):'Déjà formés'}</div><button class="ghost tiny" onclick="openFolder('${f.id}')">Dossier ↗</button></td>${stats.matrix.map(x=>`<td style="text-align:center"><button class="v19-marker-button" onclick="openFolder('${f.id}')" aria-label="Ouvrir ${esc(x.label)} pour ${esc(clientOf(f).name)}">${matrixStatus(x)}</button></td>`).join('')}<td><strong>${stats.conform}/5</strong>${progress(stats.percentage,'Complétude '+clientOf(f).name)}<small>${stats.verified} validé(s) · ${stats.toCheck} à vérifier</small></td></tr>`;}
function docMobileCard(f){let st=docStatsFor(f),name=clientOf(f).name;return `<div class="card v19-mobile-doc"><div class="card-head"><div><h3 class="section-title">${esc(name)}</h3><p class="section-caption">${esc(f.title)}</p></div>${badge(st.percentage===100?'Complet':'Incomplet')}</div><div class="v19-mini-status">${st.matrix.map(x=>`<div><span>${matrixStatus(x)}</span><small>${esc(x.key==='PROGRAMME'?'Prog.':x.key==='CADRAGE'?'Cadrage':x.label)}</small></div>`).join('')}</div><div class="folder-progress"><strong>${st.percentage}%</strong><span>${st.conform}/5 conformes · ${st.toCheck} à vérifier</span></div>${progress(st.percentage,name)}<div class="v19-inline-counts"><span>${st.missing} manquants</span><span>${st.verified} validés</span></div><button class="primary" style="width:100%" onclick="openFolder('${f.id}')">Voir les documents ↗</button></div>`;}
function docDate(f){let dates=db.sessions.filter(s=>s.formationId===f.id).map(s=>s.date).sort();let later=dates.filter(d=>d>='2026-11-13');return later[0]||dates.at(-1)||'';}
function setDocSort(value){state.docSort=value;render();}

function docLine(d,person=false){let latest=d.versions.at(-1),canUpload=person&&d.owner==='formateur'&&d.trainerId===state.trainerId;return `<div class="doc-row"><span class="doc-icon">▤</span><div class="grow"><div class="item-title">${esc(d.title)}</div><div class="item-sub">${esc(d.type)} · ${latest?'Version '+latest.number+' · '+esc(latest.filename):'Aucune version déposée'}</div></div>${badge(d.status)}${canUpload?`<button class="ghost" onclick="openModal('upload','${d.id}')">${latest?'Nouvelle version':'Déposer'} ↗</button>`:!person&&['Déposé','En vérification','Correction demandée'].includes(d.status)?`<button class="ghost" onclick="openModal('review','${d.id}')">Vérifier ↗</button>`:''}</div>`}
function documentsPage(){
 const ds=db.deliverables;
 const opts=[['all','Tous les dossiers'],['open','Incomplets'],['completed','Complets']];
 let list=formations.filter(f=>{const st=docStatsFor(f);return (state.filter==='all'||(state.filter==='open'&&st.percentage<100)||(state.filter==='completed'&&st.percentage===100))&&(f.title+' '+clientOf(f).name).toLowerCase().includes(state.search.toLowerCase());});
 if(state.docSort==='name')list.sort((a,b)=>clientOf(a).name.localeCompare(clientOf(b).name,'fr'));
 else if(state.docSort==='worst')list.sort((a,b)=>docStatsFor(a).percentage-docStatsFor(b).percentage);
 else list.sort((a,b)=>docDate(a).localeCompare(docDate(b)));
 const totals=formations.map(f=>docStatsFor(f)),full=totals.filter(t=>t.percentage===100).length;
 const buttons=`<div class="toolbar v19-doc-tools"><div class="group"><button class="${state.docSort==='calendar'?'primary':'secondary'} tiny" onclick="setDocSort('calendar')">Calendrier</button><button class="${state.docSort==='worst'?'primary':'secondary'} tiny" onclick="setDocSort('worst')">Les plus incomplets</button><button class="${state.docSort==='name'?'primary':'secondary'} tiny" onclick="setDocSort('name')">A à Z</button></div><button class="secondary tiny" onclick="flash('Google Drive et Agenda non connectés dans la démo')">Revérifier (démo)</button></div>`;
 const totalCards=`<div class="v19-doc-summary"><div class="card"><small>Dossiers complets</small><strong>${full}/${formations.length}</strong></div>${documentColumns.map(([key,label])=>{let n=formations.filter(f=>docStatsFor(f).matrix.find(x=>x.key===key)?.status==='ok').length;return `<div class="card"><small>${esc(label)}</small><strong>${n}/${formations.length}</strong></div>`}).join('')}</div>`;
 const grouped=(label,items)=>items.length?`<h3 class="v19-doc-group">${label} <small>${items.length}</small></h3><div class="v19-mobile-docs">${items.map(docMobileCard).join('')}</div>`:'';
 const coming=list.filter(f=>db.sessions.some(s=>s.formationId===f.id&&s.status!=='Réalisée'));
 const past=list.filter(f=>!coming.includes(f));
 return `${intro('Livrables <em>& bilans.</em>','Dossiers clients, à préparer et à boucler : présence, conformité, validation et relances.')}
 <div class="toolbar"><span class="badge purple">Données fictives · Google Drive non connecté</span></div>
 ${totalCards}
 ${filtersBar('Rechercher un client ou une formation…',opts)}${buttons}
 <div class="v19-doc-desktop"><div class="table-wrap"><table class="tbl v19-matrix"><thead><tr><th>Client</th>${documentColumns.map(x=>`<th>${esc(x[1])}</th>`).join('')}<th>Complétude</th></tr></thead><tbody>${list.map(docGridRow).join('')||'<tr><td colspan="7">Aucun dossier.</td></tr>'}</tbody></table></div></div>
 <div class="v19-doc-mobile">${grouped('À venir, à préparer',coming)}${grouped('Déjà formés',past)}${list.length?'':'<div class="empty">Aucun dossier.</div>'}</div>
 <div class="v19-doc-legend"><span>${matrixStatus({status:'ok',label:'Conforme'})} Présent conforme</span><span>${matrixStatus({status:'part',label:'Non conforme'})} À corriger (format)</span><span>${matrixStatus({status:'miss',label:'Manquant'})} Manquant</span></div>
 <p class="footnote">Une coche atteste la conformité de présence/format dans cette démo, pas la validation métier du contenu. Les fichiers n'ont pas été vérifiés sur Google Drive.</p>
 <div class="card" style="margin-top:18px">${cardTitle('Suivi des relances','Rappel PWA puis WhatsApp 48 h après : démonstration uniquement')}${db.reminders.map(r=>`<div class="line-item"><div class="grow"><strong>${esc(db.deliverables.find(d=>d.id===r.deliverableId)?.title||'Livrable')}</strong><div class="item-sub">${esc(r.channel)} · ${esc(r.status)} · ${esc(r.at)}</div></div></div>`).join('')||'<div class="empty">Aucune relance.</div>'}<button class="secondary tiny" onclick="simulateDueReminders()">Vérifier les rappels</button> <button class="secondary tiny" onclick="testReminderAfter48h()">Tester 48 h (démo)</button></div>`;
}
function openFolder(id){state.selectedDocGroup=id;openModal('folder',id)}
function simulatePwaReminder(id){let d=db.deliverables.find(x=>x.id===id);if(!d||d.status==='Validé'||d.versions?.length>0)return flash('Livrable déjà déposé ou non éligible');if(d.owner!=='formateur')return flash('Relance formateur non applicable');if(db.reminders.some(r=>r.deliverableId===id&&r.channel==='PWA'))return flash('Premier rappel déjà envoyé dans la démo');db.reminders.push({id:'R'+Date.now(),deliverableId:id,channel:'PWA',status:'Simulée — non envoyée',at:new Date().toISOString()});log('Rappel PWA simulé',id);closeModal();flash('Notification PWA simulée · aucun push réel')}
function simulateDueReminders(silent=false){let now=Date.now(),due=db.reminders.filter(r=>r.channel==='PWA'&&now-Date.parse(r.at)>=48*3600000);let count=0;for(let r of due){let d=db.deliverables.find(x=>x.id===r.deliverableId);if(!d||d.status==='Validé'||d.versions?.length>0||db.reminders.some(z=>z.deliverableId===r.deliverableId&&z.channel==='WhatsApp'))continue;db.reminders.push({id:'R'+Date.now()+'-'+count,deliverableId:d.id,channel:'WhatsApp',status:'Automatisation simulée — aucun envoi',at:new Date().toISOString()});count++}if(count)log('Relances WhatsApp simulées',count+' livrable(s)');if(count&&!silent){render();flash(count+' seconde(s) relance(s) WhatsApp simulée(s)')}else if(!silent)flash('Aucune seconde relance éligible après 48 h');return count}
function testReminderAfter48h(){let r=db.reminders.find(x=>x.channel==='PWA'&&!db.reminders.some(y=>y.deliverableId===x.deliverableId&&y.channel==='WhatsApp'));if(!r)return flash('Commencez par simuler un premier rappel PWA depuis un livrable manquant');r.at=new Date(Date.now()-49*3600000).toISOString();save();simulateDueReminders();render();flash('Simulation : 49 h écoulées, WhatsApp enregistré sans envoi réel')}
function docFolder(id,person=false){
 const f=formations.find(x=>x.id===id);if(!f)return '<div class="empty">Dossier introuvable.</div>';
 const docs=db.deliverables.filter(d=>d.formationId===id&&(!person||(d.owner==='formateur'&&d.trainerId===state.trainerId)));
 const st=docStatsFor(f,person);
 const top=`<div class="folder-header"><strong>${esc(clientOf(f).name)} · ${esc(f.title)}</strong><span>${st.percentage}% conformes</span></div>${progress(st.percentage,'Dossier '+clientOf(f).name)}<div class="v19-inline-counts"><span>${st.missing} manquant(s)</span><span>${st.toCheck} à vérifier</span><span>${st.verified} validé(s)</span></div>`;
 const items=(person?docs.map(d=>({d,key:docCategory(d),label:d.title,status:docConformity(d)})):st.matrix);
 return top+items.map(item=>{const d=item.d;let detail=d?.versions.at(-1),isOwner=d?.owner==='formateur'&&d.trainerId===state.trainerId;
 return `<div class="doc-row"><span>${matrixStatus(item)}</span><div class="grow"><strong>${esc(item.label)}</strong><div class="item-sub">${d?esc(d.status)+' · '+d.versions.length+' version(s) · Échéance '+fmtDate(d.dueDate):'Aucun livrable référencé dans cette catégorie'}</div>${detail?`<div class="item-sub">Dernière version : ${esc(detail.filename)}</div>`:''}</div><div class="action-wrap">${person?(isOwner?`<button class="secondary tiny" onclick="openModal('upload','${d.id}')">Déposer</button>`:''):d?`<button class="secondary tiny" onclick="openModal('upload-internal','${d.id}')">Déposer</button>${d.versions.length?`<button class="secondary tiny" onclick="openModal('review','${d.id}')">Vérifier</button>`:''}${d.owner==='formateur'&&d.status==='À fournir'?`<button class="secondary tiny" onclick="simulatePwaReminder('${d.id}')">Rappel PWA</button>`:''}`:`<button class="secondary tiny" onclick="prepareMissingDoc('${f.id}','${item.key}')">Créer et déposer</button>`}</div></div>`;
 }).join('')+`<p class="footnote">Les liens Drive et le transfert de fichiers seront disponibles après connexion du stockage. Cette version enregistre seulement les noms en démo.</p>`;
}
function prepareMissingDoc(id,key){if(state.role==='formateur')return flash('Accès réservé à l’équipe interne');let f=formations.find(x=>x.id===id),type=documentColumns.find(x=>x[0]===key);if(!f||!type)return flash('Type inconnu');let existing=db.deliverables.find(d=>d.formationId===id&&docCategory(d)===key);if(existing)return openModal('upload-internal',existing.id);let did='D'+(Math.max(0,...db.deliverables.map(d=>Number(String(d.id).slice(1))||0))+1);db.deliverables.push({id:did,formationId:id,sessionId:f.sessionIds[0],title:type[1],type:key,owner:'interne',status:'À fournir',versions:[]});log('Livrable manquant créé en démo',`${did} · ${key}`);openModal('upload-internal',did);}
function reportingPage(){let month=state.monthlyMonth,within=s=>s.date?.startsWith(month),ss=db.sessions.filter(within),aa=db.assignments.filter(a=>ss.some(s=>s.id===a.sessionId)&&['Confirmée','Réalisée'].includes(a.status)),d=db.deliverables.filter(x=>ss.some(s=>s.id===x.sessionId)),delivered=d.filter(x=>x.versions.length>0),onTime=delivered.filter(x=>x.versions.at(-1)?.at&&x.versions.at(-1).at.slice(0,10)<=x.dueDate).length;let perTrainer=trainers.map(t=>{let assignments=aa.filter(a=>a.trainerId===t.id),rate=reliabilityScore(t);return {t,assignments,rate}}).filter(x=>x.assignments.length>0);return `${intro('Monthly <em>AMO.</em>','Reporting mensuel des formations, du staffing, du NPS, des cartons et de la ponctualité documentaire.')}<div class="toolbar"><div class="group"><label for="report-month">Période</label><input id="report-month" class="field" type="month" value="${esc(month)}" onchange="state.monthlyMonth=this.value;render()"><button class="secondary tiny" onclick="exportMonthly()">Exporter le rapport CSV</button></div><span class="badge purple">Données fictives · pondérations non validées</span></div><div class="cards">${metric('Sessions',ss.length,'Dans la période')}${metric('Affectations',aa.length,'Confirmées / réalisées')}${metric('Formateurs mobilisés',perTrainer.length,'Profils distincts')}${metric('Livrables déposés',delivered.length+'/'+d.length,'Sur la période')}</div><div class="two-col"><div class="card">${cardTitle('Activité des formateurs','Missions et clients couverts sur la période')}<div class="table-wrap"><table class="tbl"><thead><tr><th>Formateur</th><th>Missions</th><th>Clients</th><th>NPS indicatif</th></tr></thead><tbody>${perTrainer.map(x=>`<tr><td>${esc(x.t.name)}</td><td>${x.assignments.length}</td><td>${[...new Set(x.assignments.map(a=>clientOf(formOf(sessionById(a.sessionId))).name))].map(esc).join(', ')}</td><td>${trainerProfileField(x.t.id).nps??'Non renseigné'}</td></tr>`).join('')||'<tr><td colspan="4">Aucune affectation dans la période</td></tr>'}</tbody></table></div></div><div class="card">${cardTitle('Ponctualité et fiabilité','Échantillon fictif, ne sert pas à évaluer des personnes réelles')}<div class="line-item"><div class="grow">Livrables déposés avant échéance (données disponibles)</div><strong>${delivered.length?Math.round(onTime/delivered.length*100)+'%':'Non mesurable'}</strong></div><div class="line-item"><div class="grow">Pool Numéro 10 (référentiel fictif)</div><strong>${trainers.filter(t=>t.rating.includes('Numéro 10')).length}</strong></div><div class="line-item"><div class="grow">Cartons rouges</div><strong>${trainers.filter(t=>trainerProfileField(t.id).redCard).length}</strong></div><p class="footnote">Le score de fiabilité avec bonus/malus est une grille proposée, non validée ni appliquée. Les évaluations par mission et causes des retards restent nécessaires pour des résultats fiables.</p></div></div><div class="card" style="margin-top:18px">${cardTitle('Grille proposée de fiabilité','À valider métier avant tout score calculé ou décision')}<div class="table-wrap"><table class="tbl"><thead><tr><th>Critère</th><th>Poids proposé</th><th>Base de calcul attendue</th></tr></thead><tbody><tr><td>Ponctualité des livrables</td><td>30 %</td><td>Versions déposées avant échéance et responsabilités identifiées</td></tr><tr><td>NPS et satisfaction</td><td>40 %</td><td>Évaluations contextualisées par session</td></tr><tr><td>Retours de mission</td><td>10 %</td><td>Débriefs et incidents vérifiés</td></tr><tr><td>Incidents vérifiés</td><td>20 %</td><td>Justifications, sources et possibilité de rectification</td></tr></tbody></table></div><p class="footnote">Aucun bonus ou malus réel calculé ou appliqué. Les critères peuvent être modifiés après concertation.</p></div>`}
function exportMonthly(){let month=state.monthlyMonth,rows=[['Mois','Formateur','Client','Session','État affectation']];for(let a of db.assignments){let s=sessionById(a.sessionId);if(!s?.date.startsWith(month))continue;rows.push([month,trainerById(a.trainerId)?.name||'',clientOf(formOf(s)).name,formOf(s).title,a.status])}let content='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');let b=new Blob([content],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='Monthly-AMO-'+month+'-DEMO.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);flash('Rapport mensuel fictif exporté')}
function trainerHome(){let t=trainerById(state.trainerId),props=db.proposals.filter(p=>p.trainerId===t.id&&p.status==='Envoyée'),aa=db.assignments.filter(a=>a.trainerId===t.id&&a.status==='Confirmée'),docs=db.deliverables.filter(d=>d.trainerId===t.id&&d.status!=='Validé');return `${intro('Bonjour <em>'+esc(t.name.split(' ')[0])+'.</em>','Retrouvez vos missions, vos documents et vos prochaines échéances.','ESPACE FORMATEUR · DONNÉES FICTIVES')}<div class="banner"><h2>Vos formations, au même endroit.</h2><p>Un espace dédié aux missions Certif-IA, aux documents à transmettre et à la gestion des disponibilités.</p><button class="primary" onclick="go('trainer-missions')">Mes missions →</button></div><div class="cards" style="margin-top:20px">${metric('Missions confirmées',aa.length,'À venir','trainer-missions','upcoming')}${metric('Propositions reçues',props.length,'À examiner','trainer-missions','proposals')}${metric('Documents à suivre',docs.length,'Livrables concernés','trainer-docs','open')}${metric('Agenda personnel','Démo','Aucune connexion Google','trainer-calendar')}</div><div class="two-col"><div class="card">${cardTitle('Mes prochaines missions')}${aa.map(a=>{let s=sessionById(a.sessionId);return `<div class="line-item"><div class="datebox"><strong>${s.date.slice(8)}</strong><small>${fmtDate(s.date,{month:'short'})}</small></div><div class="grow"><strong>${esc(clientOf(formOf(s)).name)}</strong><div class="item-sub">${fmtDate(s.date)} · ${esc(s.city)}</div></div>${badge(a.status)}</div>`}).join('')||'<div class="empty">Aucune mission confirmée.</div>'}</div><div class="card">${cardTitle('À traiter')}${props.map(p=>`<div class="task"><span class="bubble">✉</span><div class="grow"><strong>Répondre à une proposition</strong><p>${esc(clientOf(formOf(sessionById(p.sessionId))).name)}</p></div><button class="ghost" onclick="go('trainer-missions')">↗</button></div>`).join('')}${docs.slice(0,3).map(d=>`<div class="task"><span class="bubble">📄</span><div class="grow"><strong>${esc(d.title)}</strong><p>${esc(d.status)}</p></div><button class="ghost" onclick="go('trainer-docs')">↗</button></div>`).join('')||'<div class="empty">Aucune action à traiter.</div>'}</div></div>`}
function trainerMissions(){let tid=state.trainerId,props=db.proposals.filter(p=>p.trainerId===tid),aa=db.assignments.filter(a=>a.trainerId===tid),tab=state.missionTab;return `${intro('Mes <em>missions.</em>','Propositions, missions confirmées et préparation, sans affichage des informations internes.','ESPACE FORMATEUR')}<div class="tabs">${[['proposals','Propositions'],['upcoming','À venir'],['prepare','À préparer'],['finished','Terminées']].map(([k,l])=>`<button class="${tab===k?'selected':''}" onclick="changeTab('missionTab','${k}')">${l}</button>`).join('')}</div>${tab==='proposals'?`<div class="card">${cardTitle('Propositions reçues','Accepter ne confirme pas automatiquement la mission')}${props.map(p=>{let s=sessionById(p.sessionId);return `<div class="line-item"><div class="grow"><strong>${esc(clientOf(formOf(s)).name)} — ${esc(formOf(s).title)}</strong><div class="item-sub">${fmtDate(s.date)} · ${s.start}–${s.end} · ${esc(s.city)} · ${esc(p.conditions)}</div></div>${badge(p.status)}${p.status==='Envoyée'?`<div class="action-wrap"><button class="primary tiny" onclick="respondProposal('${p.id}','Acceptée')">Accepter</button><button class="secondary tiny" onclick="respondProposal('${p.id}','Refusée')">Refuser</button></div>`:''}${p.status==='Acceptée'?'<span class="item-sub">En attente de confirmation interne</span>':''}</div>`}).join('')||'<div class="empty">Aucune proposition.</div>'}</div>`:`<div class="card">${cardTitle(tab==='upcoming'?'Missions confirmées':tab==='prepare'?'Préparation de mes missions':'Missions terminées')}${aa.filter(a=>tab==='finished'?a.status==='Réalisée':tab==='prepare'?a.status==='Confirmée':a.status==='Confirmée').map(a=>{let s=sessionById(a.sessionId);return `<div class="line-item"><div class="datebox"><strong>${s.date.slice(8)}</strong><small>${fmtDate(s.date,{month:'short'})}</small></div><div class="grow"><strong>${esc(clientOf(formOf(s)).name)}</strong><div class="item-sub">${esc(formOf(s).title)} · ${esc(s.city)} · ${s.start}–${s.end}</div></div>${badge(a.status)}<span class="badge">Audit : ${db.deliverables.some(d=>d.formationId===s.formationId&&docCategory(d)==='AUDIT'&&d.versions?.length)?'reçu (démo)':'en attente'}</span><button class="ghost" onclick="openModal('mission-info',${s.id})">Client, audit & retours ↗</button><button class="ghost" onclick="go('trainer-docs')">Documents ↗</button></div>`}).join('')||'<div class="empty">Aucune mission dans cette catégorie.</div>'}</div>`}`}
function trainerCalendar(){return `${intro('Mon <em>agenda.</em>','Vos missions et vos déclarations de disponibilité. Aucune information privée visible côté Certif-IA.','ESPACE FORMATEUR')}<div class="card" style="margin-bottom:18px">${cardTitle('Connexion Google Agenda','À venir — aucune autorisation demandée dans cette démo')}<span class="badge amber">Non connecté</span> <button class="secondary tiny" onclick="flash('Connexion Google non disponible dans la démo')">Connexion à prévoir</button></div>${calendarUI(true)}<div class="card" style="margin-top:18px">${cardTitle('Déclarer un créneau','Saisie locale sans synchronisation externe')}<div class="toolbar"><div class="group"><button class="primary" onclick="openModal('availability')">+ Ajouter une disponibilité</button></div></div>${db.availability.filter(a=>a.trainerId===state.trainerId).map(a=>`<div class="line-item"><div class="grow"><strong>${fmtDate(a.date)}</strong><div class="item-sub">${esc(a.start||'Journée entière')} ${a.end?'– '+esc(a.end):''} · ${esc(a.zone||'Zone non précisée')} · ${esc(a.source)}</div></div>${badge(a.status)}</div>`).join('')||'<div class="empty">Aucun créneau déclaré : disponibilité inconnue.</div>'}</div>`}
function trainerDocs(){
 const tid=state.trainerId,assigned=db.assignments.filter(a=>a.trainerId===tid&&['Confirmée','Réalisée'].includes(a.status)).map(a=>a.sessionId);
 const ds=db.deliverables.filter(d=>d.owner==='formateur'&&d.trainerId===tid&&(assigned.includes(d.sessionId)||db.proposals.some(p=>p.sessionId===d.sessionId&&p.trainerId===tid)));
 const ids=[...new Set(ds.map(d=>d.formationId))];
 let list=ids.filter(id=>state.trainerDocsFilter==='all'||pctFor(ds.filter(d=>d.formationId===id))<100);
 return `${intro('Mes <em>livrables.</em>','Mes dossiers par client et mission, documents reçus, manquants et en validation.','ESPACE FORMATEUR')}
 <div class="toolbar"><div class="group"><button class="${state.trainerDocsFilter==='all'?'primary':'secondary'} tiny" onclick="changeTab('trainerDocsFilter','all')">Tous</button><button class="${state.trainerDocsFilter==='open'?'primary':'secondary'} tiny" onclick="changeTab('trainerDocsFilter','open')">À compléter</button></div><span class="badge purple">Aucun document transféré réellement</span></div>
 <div class="folder-grid">${list.map(id=>{let f=formations.find(f=>f.id===id),items=ds.filter(d=>d.formationId===id),pct=pctFor(items),missing=items.filter(d=>!d.versions.length||d.status==='Correction demandée').length,valid=items.filter(d=>d.status==='Validé').length,check=items.filter(d=>['Déposé','En vérification'].includes(d.status)).length;return `<div class="card folder-card"><div class="card-head"><div><h3 class="section-title">${esc(clientOf(f).name)}</h3><p class="section-caption">${esc(f.title)}</p></div>${badge(pct===100?'Tous déposés':'À compléter')}</div><div class="v19-inline-counts"><span>${missing} manquant(s)</span><span>${check} à vérifier</span><span>${valid} validé(s)</span></div><div class="folder-progress"><strong>${pct}%</strong><span>des documents déposés</span></div>${progress(pct,clientOf(f).name)}<button class="primary" style="width:100%" onclick="openModal('trainer-folder','${id}')">Parcourir / déposer les documents ↗</button></div>`}).join('')||'<div class="empty">Aucun dossier correspondant.</div>'}</div>
 <p class="footnote">100 % déposé ne signifie pas 100 % validé. Les cartons et appréciations internes AMO ne sont jamais affichés dans ce portail.</p>`;
}
function trainerProfile(){let t=trainerById(state.trainerId);return `${intro('Mon <em>profil.</em>','Vos informations déclarées et vos expertises. Les catégories internes restent confidentielles.','ESPACE FORMATEUR')}<div class="detail-grid"><div class="card"><div class="trainer-top">${trainerAvatar(t,70)}<div><h2 class="section-title">${esc(t.name)}</h2><div class="trainer-meta">${esc(t.city)} · Profil fictif</div></div></div><div class="info-grid">${[['Nom',t.name],['Ville',t.city],['Email',t.email],['Expertises déclarées',t.skills.join(', ')],['Expertises vérifiées',t.verified.join(', ')||'Aucune pour l’instant'],['Disponibilités',t.available==='unknown'?'Inconnues':t.available==='yes'?'Déclarées disponibles':'Occupé déclaré']].map(([k,v])=>`<div class="info"><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><p class="footnote">La modification réelle du profil et la vérification des expertises nécessitent authentification et validation métier.</p></div><div class="card">${cardTitle('Préférences et confidentialité')}<div class="notif">Votre profil ne révèle ni la classification interne, ni les tarifs des autres formateurs.</div><button class="secondary" style="margin-top:15px" onclick="flash('Modification du profil indisponible dans cette démo')">Modifier le profil (bientôt)</button></div></div>`}

function missionAuditDisplay(s){let d=db.deliverables.find(d=>d.formationId===s.formationId&&docCategory(d)==='AUDIT');let ready=!!d?.versions?.length;return `<div class="info"><small>Audit client</small><strong>${ready?'Reçu — démo':'En attente'}</strong><p class="item-sub">${ready?'Audit référencé dans le dossier : accès réel au document après connexion Drive.':'L’audit n’a pas encore été reçu pour cette mission.'}</p></div>`;}
function missionPublicFeedback(s){let a=db.assignments.find(a=>a.sessionId===s.id&&a.trainerId===state.trainerId),r=a&&missionRatings[a.id];if(!r||!r.public)return '<div class="info"><small>Retour client</small><strong>Pas encore communiqué</strong></div>';return `<div class="info"><small>Évaluations communicables — données fictives</small><strong>NPS ${esc(r.nps??'—')}/10 · Note Certif ${esc(r.certif??'—')}/10 · Participants ${esc(r.participants??'—')}/10</strong><p class="item-sub">Mission ${esc(r.period)} · Ponctualité documentaire : à mesurer.</p></div>`;}

function modalView(){let m=state.modal,out='';if(m.kind==='reschedule'||m.kind==='edit-session'){let s=sessionById(m.id),assigned=activeAssignments(s.id);out=modalBox('Modifier une session','Date, heures, lieu, modalité et affectations : toute modification substantielle exige une revalidation.',`<div class="form-grid"><label>Date<input class="field" id="new-date" type="date" value="${s.date}"></label><label>Début<input class="field" id="new-start" type="time" value="${s.start}"></label><label>Fin<input class="field" id="new-end" type="time" value="${s.end}"></label><label>Ville / lieu<input class="field" id="new-city" value="${esc(s.city)}"></label><label>Adresse (facultatif)<input class="field" id="new-address" value="${esc(s.address||'')}"></label><label>Modalité<select class="field" id="new-modality">${['Présentiel','Distanciel','Hybride'].map(v=>`<option ${s.modality===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Formateur principal<select class="field" id="new-trainer"><option value="">Ne pas modifier</option>${trainers.map(t=>`<option value="${t.id}" ${assigned.length&&assigned[0].trainerId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="notif">${assigned.length} affectation(s) existante(s). Après modification, leurs statuts seront « À revalider » si nécessaire. L'AMO doit contrôler la capacité et les conflits.</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Annuler</button><button class="primary" onclick="saveSessionEdit(${s.id})">Enregistrer les modifications (démo)</button></div>`)}
else if(m.kind==='availability'){out=modalBox('Déclarer un créneau','Horaires précis, disponible/occupé, zone géographique facultative. Motifs privés masqués.',`<div class="form-grid"><label>Date<input class="field" id="avail-date" type="date" value="${state.calendarDate}"></label><label>État<select class="field" id="avail-status"><option>Disponible</option><option>Occupé</option></select></label><label>Début<input class="field" id="avail-start" type="time" value="09:00"></label><label>Fin<input class="field" id="avail-end" type="time" value="17:00"></label><label>Zone géographique facultative<input class="field" id="avail-zone" placeholder="Paris, Lyon, à distance…" maxlength="100"></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Annuler</button><button class="primary" onclick="addAvailability()">Enregistrer (démo)</button></div>`)}
else if(m.kind==='matching'){let t=trainerById(m.id),s=sessionById(state.selectedSession),c=compatDetails(t,s);out=modalBox('Pourquoi ce score de compatibilité ?',`Grille de démonstration transparente — ${t.name}`,`<div class="compat-hero">${c.total}% ${badge(c.eligible?'Éligibilité à confirmer':'Blocage possible')}</div>${c.parts.map(([name,points,max])=>`<div class="score-detail"><div><strong>${esc(name)}</strong><span>${points}/${max} pts</span></div>${progress(Math.round(100*points/max),name)}</div>`).join('')}<div class="notif">${c.reasons.map(esc).join(' · ')}</div><p class="footnote">Pondération indicative à valider avec l'équipe : expertise 40, disponibilité 30, localisation 20, expérience 10. Aucune disponibilité inconnue ne vaut preuve de liberté. Score ≠ autorisation de staffer.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Fermer</button></div>`)}
else if(m.kind==='folder'||m.kind==='trainer-folder'){out=modalBox('Dossier de livrables',m.kind==='folder'?'Gestion interne des documents et relances':'Documents attendus pour vos missions',docFolder(m.id,m.kind==='trainer-folder')+`<div class="modal-actions"><button class="secondary" onclick="closeModal()">Fermer</button></div>`)}
else if(m.kind==='mission-info'){let s=sessionById(m.id),f=formOf(s),c=clientOf(f),d=clientDetails[c.id];out=modalBox('Informations client pour la mission','Uniquement les informations utiles au formateur, sans notes internes confidentielles.',`<div class="info-grid">${[['Client',c.name],['Formation',f.title],['Date',fmtDate(s.date)],['Horaires',s.start+'–'+s.end],['Lieu',s.address||s.city],['Contact',d.contact],['Consignes',d.notesTrainer]].map(([k,v])=>`<div class="info"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="v19-mission-extra">${missionAuditDisplay(s)}${missionPublicFeedback(s)}</div><div class="modal-actions"><a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(mapsUrl(s.address,s.city))}">Ouvrir l'itinéraire ↗</a><button class="secondary" onclick="closeModal()">Fermer</button></div><p class="footnote">L’adresse précise est à renseigner ; ici le lien indique une ville fictive.</p>`)}
else if(m.kind==='upload'||m.kind==='upload-internal'){let d=db.deliverables.find(x=>x.id===m.id);out=modalBox('Déposer un livrable','Le fichier n’est pas réellement transféré : la version et le nom sont enregistrés dans cette démo.',`<div class="info"><small>Livrable</small><strong>${esc(d.title)}</strong></div><label class="form-label" for="upload-file">Sélectionner un document</label><input type="file" class="field" id="upload-file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xlsx,.png,.jpg,.jpeg"><div class="modal-actions"><button class="secondary" onclick="closeModal()">Annuler</button><button class="primary" onclick="simulateUpload('${d.id}',${m.kind==='upload-internal'})">Simuler le dépôt</button></div>`)}
else if(m.kind==='review'){let d=db.deliverables.find(x=>x.id===m.id);out=modalBox('Vérifier un livrable','Valider la version actuelle ou demander une correction — démonstration.',`<div class="info"><small>Livrable</small><strong>${esc(d.title)}</strong></div><label class="form-label" for="review-comment">Commentaire éventuel</label><textarea class="field" id="review-comment" placeholder="Préciser la correction demandée…"></textarea><div class="modal-actions"><button class="secondary" onclick="closeModal()">Annuler</button><button class="secondary" onclick="reviewDoc('${d.id}','Correction demandée')">Demander correction</button><button class="primary" onclick="reviewDoc('${d.id}','Validé')">Valider (démo)</button></div>`)}
return `<div class="modal-back" role="presentation" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(m.kind)}"><button class="modal-close" aria-label="Fermer" onclick="closeModal()">×</button>${out}</div></div>`}
function saveSessionEdit(id){let s=sessionById(id),date=$('new-date')?.value,start=$('new-start')?.value,end=$('new-end')?.value,city=$('new-city')?.value.trim(),address=$('new-address')?.value.trim(),modality=$('new-modality')?.value,tid=Number($('new-trainer')?.value||0);if(!date||!start||!end||!city||end<=start)return flash('Date, horaires et lieu valides requis');let prev=JSON.stringify([s.date,s.start,s.end,s.city,s.address||'',s.modality]);let next=JSON.stringify([date,start,end,city,address,modality]);let changed=prev!==next;let current=activeAssignments(id);if(!changed&&(!tid||current.some(a=>a.trainerId===tid)))return flash('Aucune modification');Object.assign(s,{date,start,end,city,address,modality});if(changed||tid){current.forEach(a=>a.status='À revalider');if(tid&&!db.assignments.some(a=>a.sessionId===id&&a.trainerId===tid&&a.status==='À revalider'))db.assignments.push({id:'A'+Date.now(),sessionId:id,trainerId:tid,status:'À revalider'});}log('Modification de session démo',id+' · contrôle de revalidation requis');closeModal();flash('Modification simulée ; affectations à revalider')}
function modalBox(title,desc,content){return `<h2>${title}</h2><p>${desc}</p>${content}`}
function rescheduleSession(id){let el=$('new-date'),date=el?.value,s=sessionById(id);if(!date||!s)return flash('Date requise');if(s.date===date)return flash('La date est inchangée');let previous=s.date;s.date=date;db.assignments.filter(a=>a.sessionId===s.id&&a.status==='Confirmée').forEach(a=>a.status='À revalider');log('Report de session (démo)',`session ${id} : ${previous} → ${date}`);closeModal();flash('Session reportée ; affectations à revalider')}
function addAvailability(){let date=$('avail-date')?.value,status=$('avail-status')?.value,start=$('avail-start')?.value,end=$('avail-end')?.value,zone=$('avail-zone')?.value.trim();if(!date||!start||!end)return flash('Date et horaires requis');if(end<=start)return flash('L’heure de fin doit être après le début');db.availability.push({id:'AV'+Date.now(),trainerId:state.trainerId,date,status,start,end,zone,source:'déclaration démo'});log('Disponibilité déclarée',`formateur ${state.trainerId} : ${date} ${start}-${end}`);closeModal();flash('Créneau enregistré (simulation)')}
function simulateUpload(id,internal=false){let input=$('upload-file'),file=input?.files?.[0];if(!file)return flash('Sélectionner un fichier');let d=db.deliverables.find(x=>x.id===id);if(!d||(internal?state.role==='formateur':d.owner!=='formateur'||d.trainerId!==state.trainerId))return flash('Action non autorisée');d.versions.push({number:d.versions.length+1,filename:file.name,status:'Déposé',at:new Date().toISOString()});d.status='Déposé';log('Dépôt simulé',`${id} : ${file.name}`);closeModal();flash('Version enregistrée en démo · aucun fichier envoyé')}
function reviewDoc(id,status){let d=db.deliverables.find(x=>x.id===id);if(!d||!d.versions.length)return flash('Aucune version à vérifier');let comment=$('review-comment')?.value.trim()||'';d.status=status;d.versions.at(-1).status=status;d.versions.at(-1).comment=comment;log('Vérification documentaire simulée',`${id} : ${status}`);closeModal();flash('Décision documentaire enregistrée (simulation)')}
initV17();simulateDueReminders(true);restoreHash();render();setInterval(()=>{if(simulateDueReminders(true))render()},60000);
window.addEventListener('hashchange',()=>{restoreHash();render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal)closeModal();else if(state.mobileMore)closeMobileMore();}});